import{r as i,j as e}from"./index-Dy19eyQl.js";function r({className:n=""}){const t=i.useId().replace(/:/g,""),o=`badge-${t}`,a=`gold-${t}`;return e.jsxs("svg",{className:n,viewBox:"0 0 64 64",fill:"none",xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",children:[e.jsxs("defs",{children:[e.jsxs("linearGradient",{id:o,x1:"0",y1:"0",x2:"1",y2:"1",children:[e.jsx("stop",{offset:"0",stopColor:"#243c6e"}),e.jsx("stop",{offset:"1",stopColor:"#16233f"})]}),e.jsxs("linearGradient",{id:a,x1:"0",y1:"0",x2:"0",y2:"1",children:[e.jsx("stop",{offset:"0",stopColor:"#fbbf24"}),e.jsx("stop",{offset:"1",stopColor:"#f59e0b"})]})]}),e.jsx("rect",{width:"64",height:"64",rx:"16",fill:`url(#${o})`}),e.jsxs("g",{fill:`url(#${a})`,children:[e.jsx("polygon",{points:"11.9,14.2 52.1,14.2 47.7,20.2 15.2,20.2"}),e.jsx("polygon",{points:"29.1,19.8 34.9,19.8 34.9,45.8 31.8,52 28.7,45.8"}),e.jsx("polygon",{points:"19,22.4 27.8,22.4 26.9,29.9 22.5,29.9"}),e.jsx("polygon",{points:"38,22.4 47.3,22.4 37.1,42.7"})]})]})}const d={kicker:"Section 01 — Where Projects Start",title:"An idea nobody has built yet. Or a process still run by hand.",body:"Two different starting points, one job — turning something that today exists only in a founder’s head, or across seven disconnected tools, into software that runs.",doors:[{n:"01",title:"You have an idea",body:"A product you can describe but cannot build, and no engineering team to hand it to. Trimugo takes it from the first conversation to a live release — scope, architecture, build, launch — as a freelance engagement rather than a hire."},{n:"02",title:"You have a process",body:"Work that already happens every week, held together by email, spreadsheets and people re-typing the same values. It does not fail because anyone is careless. It fails at every handoff."}],chainLabel:"The second one, as it runs today",before:[{step:"Email",note:"The request arrives"},{step:"Spreadsheet",note:"Someone logs it by hand"},{step:"PDF documents",note:"Details are re-read and re-typed"},{step:"Manual data entry",note:"The same values, a third time"},{step:"Review",note:"Waiting on one person"},{step:"Approval",note:"Waiting on another"},{step:"Follow-up",note:"Chasing, by hand"},{step:"Reporting",note:"Rebuilt from scratch each month"}],costs:["Disconnected systems that never agree with each other","Work that stops the moment one person is unavailable","No audit trail when someone asks what happened","Reporting that is out of date before it is finished"],after:"Trimugo turns an idea into a shipped product, and a fragmented process into a connected workflow."},l={kicker:"Section 02 — The Workflow",title:"What replaces the queue.",body:"One connected path from the moment work arrives to the moment it is done and recorded. Most of it is ordinary, deterministic software — that is the point. Two stages can be handed to a model when the work involves reading unstructured documents, and those two are marked optional below.",stages:[{id:"input",label:"Business input",kind:"Ingest",note:"Email, upload, form, API or scan — the work arrives once."},{id:"understand",label:"AI understanding",kind:"Model",optional:!0,note:"Only when the incoming work is unstructured — a scanned invoice, a free-text request. A structured form skips this entirely."},{id:"extract",label:"Extraction & classification",kind:"Model",optional:!0,note:"Fields, entities and document type resolved into structured data — again, only where there is unstructured input to resolve."},{id:"validate",label:"Validation",kind:"Deterministic",note:"Types, totals, references and required fields checked in code."},{id:"rules",label:"Business rules",kind:"Deterministic",note:"Your thresholds, exceptions and routing logic — explicit, testable."},{id:"workflow",label:"Workflow",kind:"Orchestration",note:"State, ownership, queues and SLAs held by the system."},{id:"approval",label:"Approval / automation",kind:"Orchestration",note:"Cleared automatically, or routed to the person who decides."},{id:"action",label:"Human or system action",kind:"Execution",note:"Written to the ERP, CRM or database. Or handed to a person, with context."},{id:"reporting",label:"Reporting",kind:"Output",note:"Every step already recorded — the report is a read, not a rebuild."}],note:"Seven of these nine stages are deterministic code, and most projects use only those. AI enters where meaning has to be read out of an unstructured document, and nowhere else — that boundary is a decision we make with you at design time, not a default we ship."},h=[{id:"idea-to-product",n:"01",title:"Idea to First Release",body:"A described idea taken to something live — scope, data model, architecture, build and launch. The first release is built as the first increment of the real system rather than as a throwaway prototype."},{id:"applications",n:"02",title:"Business Applications",body:"Custom web applications designed around a specific business workflow rather than around a generic template — the operational portals, dashboards and internal tools a team works in all day."},{id:"mobile",n:"03",title:"Mobile Applications",body:"React Native products for customers, field teams and operations, shipped through App Store and Google Play review and maintained afterwards."},{id:"automation",n:"04",title:"Process Automation",body:"Automation of the repetitive operational tasks and manual coordination that currently consume a person’s week."},{id:"integration",n:"05",title:"System Integration",body:"Integration with the APIs, databases, CRM, ERP and third-party systems you already run — so the new workflow joins the estate instead of adding to it."},{id:"workflow-systems",n:"06",title:"Workflow Systems",body:"Workflow platforms that carry a process end to end — intake, routing, approval, execution and audit — with state and ownership held by the system rather than by a spreadsheet."},{id:"agents",n:"07",title:"AI Agents & Document Intelligence",body:"Offered when a project calls for it, not as the starting point: agents that reason over your business data within explicit boundaries, and extraction and classification of invoices, contracts and forms."}],c=[{n:"01",title:"Discover",body:"Understand the idea, or the process as it actually runs today — what it has to do, who it is for, and where it stalls."},{n:"02",title:"Design",body:"Map the target workflow and define the product, the data model and the architecture."},{n:"03",title:"Build",body:"Develop the application, the AI capability and the automation, in reviewable increments."},{n:"04",title:"Deploy",body:"Integrate with your existing systems and put it into production."},{n:"05",title:"Improve",body:"Maintain, monitor and continue developing the system after launch."}],u=[{group:"Frontend",items:["React","Vue","TypeScript","Redux / Redux Toolkit","Vuex / Pinia","Tailwind CSS","GSAP","Three.js"]},{group:"Mobile",items:["React Native"]},{group:"Backend",items:["Node.js","Express","REST APIs","PostgreSQL","MongoDB"]},{group:"AI — on request",items:["LLM integration","RAG","AI agents","Document extraction"]},{group:"Infrastructure",items:["Cloud deployment","Authentication","Authorization","Logging","Monitoring","CI/CD"]}],p=[{title:"Business-first engineering",body:"We understand the workflow before choosing the technology. The architecture follows the process, not the other way round."},{title:"AI with purpose",body:"We use AI where it creates meaningful business value, and deterministic software everywhere that has to be exact."},{title:"Custom-built systems",body:"We build around your actual process — including the exceptions that a configurable product would force you to abandon."},{title:"Direct engineering communication",body:"You talk to the engineer building the system. There is no account layer, no delivery manager and no relay between you and the work."},{title:"Long-term partnership",body:"We can keep developing and supporting the system after launch, rather than handing over a repository and leaving."}],y={line:"One engineer. No handoffs.",body:"Trimugo is run by a single full-stack engineer. The person on the first call is the person who designs the system, writes the code, ships the release and answers the message afterwards.",person:{name:"Malisetti Obulamurthy",role:"Founder · Full-Stack Engineer",body:"Eight years building production web and mobile applications — React, Vue and React Native on the front, integrated against the APIs and services behind them. Discovery, architecture, implementation and delivery are all the same person.",focus:["React, Vue and TypeScript interfaces","React Native apps shipped to both app stores","API integration, application state and data flow","Discovery, architecture and delivery ownership","AI agents and LLM integration, when a project calls for it"],hours:"Four hours a day, scheduled inside your working day rather than at the edge of it. From India (IST) that covers a full European day in CET/CEST, the US Eastern morning, and all of India and APAC; US Pacific works by arrangement.",engagement:[{label:"Availability",value:"4 hours per day"},{label:"Rate",value:"USD 15–18 / hour"},{label:"Engagement",value:"Remote, part-time, milestone or hourly"},{label:"Based in",value:"Bangalore, India · works remotely, worldwide"}],cv:{label:"Download CV",href:"/Malisetti-Obulamurthy-CV.pdf"},links:[{id:"github",label:"GitHub",href:"https://github.com/Murthy-sys?tab=repositories"},{id:"linkedin",label:"LinkedIn",href:"https://www.linkedin.com/in/obulamurthy-malisetti-b2893122b"}]}},g={statement:"We design systems with security, privacy and applicable data-protection requirements in mind.",practices:["Authentication","Authorization","Role-based access","Audit logs","Secure API integration","Data validation","Encryption where applicable","Logging","Monitoring","Cloud deployment"],caveat:"Where a project carries a specific regulatory obligation, we scope it explicitly with you and involve your compliance advisors — we do not claim certification we do not hold."},m={line:"Remote delivery. Structured communication. Direct engineering access.",body:"We work with companies wherever they are — Europe and the UK, the US, India and the wider APAC region — on a rhythm that makes progress visible without turning into a meeting schedule.",points:[{title:"Your working hours, not ours",body:"The daily block is scheduled inside your working day. From India it reaches a full European day (CET/CEST), the US Eastern morning, and all of India and APAC — so stand-ups, reviews and calls run at your hours."},{title:"Milestone-based delivery",body:"Scope agreed and invoiced against defined milestones."},{title:"Regular demos",body:"Working software shown on a fixed cadence, not slides."},{title:"Documentation",body:"Architecture, integrations and operational runbooks written down."},{title:"Transparent communication",body:"Progress, blockers and estimates reported as they change."},{title:"Direct engineering access",body:"You talk to the engineer doing the work, with no intermediary."},{title:"Post-launch support",body:"Maintenance and continued development after go-live."}]},w=[{q:"I have an idea but no technical team. Can you build it?",a:"Yes — that is one of the two ways a project starts here. You describe the product; scope, data model, architecture, build and release are handled as a freelance engagement rather than a hire. The first release is built as the first increment of the real system, so it survives if the idea works."},{q:"Is Trimugo an AI company?",a:"No. The core is product engineering — the web and mobile applications a business runs on, and the automation and integration around them. AI agents, retrieval and document extraction are things we build when a project genuinely calls for one, and we will say so plainly when it does not. One of the two systems written up on this page contains no AI at all, and it was the right call."},{q:"Can you work with our existing software?",a:"Yes. Most of what we build joins an existing estate rather than replacing it — we integrate with the systems you already run and only replace what is genuinely holding the process back."},{q:"Can you integrate with our CRM or ERP?",a:"Yes, where the system exposes an API, a database connection or a supported export. We scope the integration surface during discovery so the constraints are known before the build starts."},{q:"Can you work alongside our internal development team?",a:"Yes. We work as an engineering partner inside your process — your repositories, your review standards, your release cadence — or take a scope end to end, whichever fits."},{q:"Who actually does the work?",a:"Malisetti Obulamurthy — the founder and engineer behind Trimugo. There is no team behind the name and no subcontracting: the person you scope the project with is the person who writes the code, ships the release and supports it afterwards."},{q:"What hours do you work, and how does that overlap with my team?",a:"Four hours a day, scheduled inside your working day rather than at the edge of it. From India (IST) that block covers a full European day in CET/CEST, the US Eastern morning, and all of India and APAC; US Pacific works by arrangement. Stand-ups, reviews and calls run at your hours."},{q:"Do you work as a freelance developer or on a contract basis?",a:"Both — they are the same engineer either way. A freelance engagement is scoped project by project against defined milestones; a contract engagement is an ongoing block of hours inside your team, your repositories and your release process. Availability is four hours a day at USD 15–18 per hour, billed hourly or per milestone, and there is no agency margin or account layer on top because there is no agency."},{q:"What AI solutions do you actually build?",a:"Three things, and only where they earn their place: AI agents that reason over your business data inside explicit boundaries, retrieval over your own documents, and extraction and classification of invoices, contracts and forms. What we do not do is put a model in front of work that is better handled by deterministic code — seven of the nine stages in a typical workflow are ordinary software, and we will tell you plainly when AI is the wrong answer."},{q:"Do you build MVPs or production systems?",a:"Both, but we build MVPs as the first increment of a production system rather than as a throwaway. The architecture is chosen so the prototype can survive if it succeeds."},{q:"Can you maintain the software after launch?",a:"Yes. Maintenance, monitoring and continued development after go-live are part of what we offer, on an ongoing arrangement."},{q:"How does an AI workflow project start?",a:"With a conversation about how the process runs today — who touches it, where it waits, and what the exceptions are. That is usually enough to identify whether AI, automation, integration or plain software is the right answer, and where the value actually sits."},{q:"Do you only work with European companies?",a:"No. Engagements are remote and the client can be anywhere — Europe and the UK, the US, India or the wider APAC region. The only real constraint is a working-hours overlap, and the daily block is scheduled around your day. Delivery is structured around milestones, scheduled demos and written documentation, with direct access to the engineer doing the work."}],b=["Take an idea from scratch to a first release","Build a web application","Build a mobile app","Automate an existing workflow","Integrate existing systems","Front-end engineering on an existing product","Add an AI agent or document extraction","Other"],f=["As soon as possible","Within 1–3 months","Within 3–6 months","Exploring / no fixed date"],v=[{label:"Email",value:"murthy@trimugo.in",href:"mailto:murthy@trimugo.in"},{label:"Phone",value:"+91 85000 98088",href:"tel:+918500098088"},{label:"WhatsApp",value:"Chat with us",href:"https://wa.me/918500098088"}],k=[{id:"lumo-rentals",name:"Lumo Rentals",initials:"LR",status:"Delivered",category:"Vehicle rental platform · Web + iOS + Android",year:"2025",summary:"A vehicle rental business running bookings for bikes, cars and tempo vehicles across three surfaces — a public web app and native apps on both stores — from a single backend.",challenge:"Renting vehicles is a coordination problem before it is a software problem: what is available, for which dates, at what price, paid for by whom. Handling that across separate channels means availability is only ever correct in one person’s head.",existingWorkflow:null,solution:"A booking platform with one API behind three clients. Vehicle catalogue, availability, reservations, customer accounts and payment all live in one system, so a booking made on a phone and a booking made on the web are the same record.",ai:null,aiNote:"No AI in this build. The value here was in removing manual coordination, and adding a model would have added risk without adding capability — the same judgement we apply to every project.",automation:["Availability and reservation state maintained by the system rather than reconciled by hand","Payment capture and booking confirmation handled in-flow instead of chased afterwards","One booking record shared across web and both mobile apps"],engineering:["A single backend service and PostgreSQL data model serving three clients","React Native application shipped through both App Store and Google Play review","Payment provider integration","Availability modelling across vehicle classes and date ranges"],outcome:["Live in production on the web, the App Store and Google Play","Bookings run through one system rather than across separate channels","Customers self-serve on the surface they already use"],outcomeMetrics:null,flow:["Customer","Availability","Reservation","Payment","Confirmation","Operations"],stack:["React.js","React Native","PostgreSQL","Payments"],links:{live:"https://www.lumo.rentals/",playstore:"https://play.google.com/store/apps/details?id=com.lumo&pcampaignid=web_share",appstore:"https://apps.apple.com/in/app/lumo-rentals/id6747010129"}}],A={updated:"7 September 2026",intro:"This site sets no cookies, runs no analytics, and contains no tracking or advertising technology of any kind. The only personal data it receives is what you choose to type into the contact form. This page explains what happens to it.",controller:{name:"Trimugo — Malisetti Obulamurthy",role:"Data controller",postal:"#52/52, CK Nagar, Hosa Road, Bangalore, India",email:"murthy@trimugo.in",phone:"+91 85000 98088"},sections:[{title:"What we collect, and when",body:"Only through the contact form. Nothing is collected from you by simply reading the site.",items:["Your name, and the company you are writing on behalf of if you give one","Your work email address, and your company website if you choose to give it","What you are looking to build, and your expected timeline","Your description of where the project stands today, in your own words"],note:"Please do not put confidential business detail, personal data about third parties, or anything commercially sensitive into the form. A first message only needs enough to make the reply useful — the detail belongs in a conversation under an NDA."},{title:"Why we process it, and on what legal basis",body:"To read your enquiry and reply to it, and to carry out any work that follows from it. Under the GDPR the basis is Article 6(1)(b) — steps taken at your request before entering into a contract — and, where an enquiry does not lead to a contract, Article 6(1)(f), our legitimate interest in answering people who contact us about our work. Your data is never used for marketing, never profiled, and never sold or shared for anyone else’s purposes."},{title:"Who else touches it",items:["Web3Forms (web3forms.com) — receives the form submission and relays it to our email inbox. It is a processor acting on our instructions.","Google Workspace — the inbox the enquiry is delivered to and stored in.","Vercel — hosts this website and keeps short-lived technical server logs, including the IP address of every request, for security and diagnostics.","Google Fonts — the two typefaces on this site are requested from fonts.googleapis.com and fonts.gstatic.com when the page loads, which discloses your IP address to Google. No cookie is set by this request. If you would rather not make it, a content blocker or a browser that blocks third-party requests will stop it, and the site remains fully usable in a fallback typeface."],note:"There are no other recipients. No analytics provider, no advertising network, no session recorder, no chat widget, no A/B testing tool, and no social media pixel."},{title:"Where it goes — transfer outside the EEA",body:"Stated plainly because it matters to a European client: Trimugo operates from India, which is a third country without an EU adequacy decision. When you send the form, your enquiry is read and answered in India. For an enquiry you send us yourself, the transfer relies on Article 49(1)(b) of the GDPR — it is necessary to take steps at your request before a contract. Where we go on to work together and personal data is processed as part of that work, the transfer is put on a proper footing in the contract, with Standard Contractual Clauses and a data processing agreement, before any such processing begins."},{title:"How long it is kept",body:"An enquiry that does not lead to work is deleted once it is clear there is nothing to follow up — in any case within twelve months. An enquiry that does lead to work is kept for the duration of the engagement and afterwards only for as long as we have a legal or contractual reason to keep it. Server logs at the host are short-lived and rotate automatically."},{title:"Your rights",body:"If you are in the EU or the EEA, the GDPR gives you the right to ask for a copy of the personal data we hold about you, to have it corrected, to have it erased, to restrict or object to how it is processed, and to receive it in a portable form. Ask by email and we will act on it within one month, free of charge. You also have the right to complain to the data protection authority in your own country if you are not satisfied with how we have handled it."},{title:"Security",body:"The site is served over HTTPS only. The contact form is submitted over an encrypted connection and posted straight to the relay — it is never written to a database on this site, because this site has no database and no server-side storage of its own. Access to the inbox holding enquiries is protected by two-factor authentication."},{title:"Children",body:"This is a business-to-business site. It is not directed at children and we do not knowingly collect personal data from anyone under 16."},{title:"Changes",body:"If this policy changes, the date at the top of the page changes with it. There is no mailing list to notify, because we do not run one."}]};export{r as L,l as a,k as b,v as c,b as d,c as e,w as f,u as g,p as h,y as i,g as j,m as k,A as l,d as p,h as s,f as t};
